sys_script_include.script:
function IsPotentialTechnicalUser(vUser)
{
	var grUser = GetUserRecord(vUser);
	if (IsValidRecord(grUser) == false)
	{
		return false;
	}

	if (IsTechnicalUser(grUser) == true)
	{
		return true;
	}

	if (grUser.internal_integration_user == true)	
	{
		return true;
	}
	if (grUser.web_service_access_only == true)
	{
		return true;
	}
	if (grUser.identity_type == 'machine')
	{
		return true;
	}

	var aFragments = [
		'technical',
		'Technical',
		'Integration',
		'integration',
		'Service',
		'service'];

	var strUserName = GetStringValue(grUser.user_name);
	var strFirstName = GetStringValue(grUser.first_name);
	var strLastName = GetStringValue(grUser.last_name);

	for (var nFragment = 0; nFragment < aFragments.length; nFragment++)
	{
		var strFragment = aFragments[nFragment];
		if (strUserName.indexOf(strFragment) != -1)
		{
			return true;
		}
		if (strFirstName.indexOf(strFragment) != -1)
		{
			return true;
		}
		if (strLastName.indexOf(strFragment) != -1)
		{
			return true;
		}		
	}

	return false;
}
